class InputCell:
    def __init__(self, initial_value):
        self.value = initial_value
        self._dependents = set()

    def set_value(self, new_value):
        # If nothing changed, do nothing.
        if self.value == new_value:
            return
        self.value = new_value

        # Collect all affected compute cells (transitive dependents)
        affected = set()
        stack = list(self._dependents)
        while stack:
            node = stack.pop()
            if node in affected:
                continue
            affected.add(node)
            stack.extend(node._dependents)

        if not affected:
            return

        # Save previous values to decide which callbacks to call
        previous_values = {cell: cell.value for cell in affected}

        # Iteratively recompute affected compute cells until stable
        # (Works because dependency graph is a DAG; will converge in finite steps)
        changed = True
        while changed:
            changed = False
            for cell in affected:
                # Compute using current input values
                vals = [inp.value for inp in cell.inputs]
                try:
                    new_val = cell.compute_function(vals)
                except Exception:
                    # If compute function throws, skip updating this cell
                    continue
                if cell.value != new_val:
                    cell.value = new_val
                    changed = True

        # After stable, call callbacks for cells whose value changed.
        for cell in affected:
            old = previous_values.get(cell)
            new = cell.value
            if old != new:
                # Call callbacks in registration order; exceptions swallowed
                for cb in list(cell._callbacks):
                    try:
                        cb(new)
                    except Exception:
                        pass


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self.inputs = list(inputs)
        self.compute_function = compute_function
        self._callbacks = []
        self._dependents = set()

        # Register self as dependent on each input
        for inp in self.inputs:
            if not hasattr(inp, "_dependents"):
                inp._dependents = set()
            inp._dependents.add(self)

        # Compute initial value
        vals = [inp.value for inp in self.inputs]
        self.value = compute_function(vals)

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
